#!/bin/bash
# f5.7i (QA f5.7g): pre-push checks for UI pushes, run from the repo root before `git push origin HEAD:main`.
# Serves the tree on $PORT, runs targeted unit tests + sim_ui + ui_budget (--strict default), one browser at a time, then stops the server.
set -u; PORT=${PORT:-8958}; cd "$(dirname "$0")/.."; fail=0
python3 -m http.server $PORT >/dev/null 2>&1 & SRV=$!; trap 'kill $SRV 2>/dev/null' EXIT; sleep 1
# 2026-11-01: all tests/*.mjs in parallel (syntax check + ~74 unit tests, ~3 min vs ~15 min serial). FAST=1 skips the browser smokes below.
node tests/prepush.mjs ${PREPUSH_ARGS:-} 2>&1 | tee /tmp/prepush_unit.log | grep -E '^(syntax|tests|FAIL|SYNTAX|KNOWN)' ; [ ${PIPESTATUS[0]} = 0 ] || { echo "FAIL unit (tests/prepush.mjs)"; fail=1; }
[ -n "${FAST:-}" ] && { [ $fail = 0 ] && echo "prepush (FAST, no browser smokes) OK" || echo "prepush FAILED"; exit $fail; }
U=http://localhost:$PORT/ OUT=${OUT:-/tmp/prepush_sim_ui} node tests/smoke/sim_ui.cjs >/tmp/prepush_sim_ui.log 2>&1 || { echo "FAIL sim_ui"; fail=1; }; tail -2 /tmp/prepush_sim_ui.log
node tests/smoke/audio_stop.cjs http://localhost:$PORT/ >/tmp/prepush_audio_stop.log 2>&1 || { echo "FAIL audio_stop"; fail=1; }; tail -1 /tmp/prepush_audio_stop.log # f5.8y: no engine/wind loop survives the flight screen
node tests/smoke/audio_music.cjs http://localhost:$PORT/ >/tmp/prepush_audio_music.log 2>&1 || { echo "FAIL audio_music"; fail=1; }; tail -1 /tmp/prepush_audio_music.log # f6.3: menu beat, space score, pause silence, crackle/distance mix, music settings
U=http://localhost:$PORT/ node tests/hero_models.cjs >/tmp/prepush_hero_models.log 2>&1 || { echo "FAIL hero_models"; fail=1; }; tail -1 /tmp/prepush_hero_models.log # f5.8s: nothing past the nose / no floating dress, every model and tier
U=http://localhost:$PORT/ node tests/smoke/hero_follow.cjs >/tmp/prepush_hero_follow.log 2>&1 || { echo "FAIL hero_follow"; fail=1; }; tail -1 /tmp/prepush_hero_follow.log # f5.8r: hero model follows the sim on 3 rockets (phone), no page errors / [Orbit Rush] warnings
U=http://localhost:$PORT/ STRIDE=${LAUNCH_STRIDE:-6} node tests/smoke/launch_all.cjs >/tmp/prepush_launch_all.log 2>&1 || { echo "FAIL launch_all"; fail=1; }; tail -1 /tmp/prepush_launch_all.log # f5.9-0: every roster rocket launches from Home (no Build), deep links fall back to Home
U=http://localhost:$PORT/ OUT=/tmp/prepush_terrain VIEWS=1280x800 PITCH=0.65 node tests/smoke/terrain_blend.cjs 1 20 44 100 >/tmp/prepush_terrain.log 2>&1 || { echo "FAIL terrain_blend"; fail=1; }; tail -1 /tmp/prepush_terrain.log # f5.9: the near-field ground tile fades into the globe (no round edge / pop), 1/20/44/100 km
U=http://localhost:$PORT/ NO_BROWSER= node tests/staged_models.cjs >/tmp/prepush_staged_models.log 2>&1 || { echo "FAIL staged_models"; fail=1; }; tail -1 /tmp/prepush_staged_models.log # f6.0: Blender stage assets: manifests, budgets, nozzles vs plume table, builds at every tier
U=http://localhost:$PORT/ LIMIT=${STAGED_LAUNCH_LIMIT:-1} node tests/staged_launch.cjs >/tmp/prepush_staged_launch.log 2>&1 || { echo "FAIL staged_launch"; fail=1; }; tail -1 /tmp/prepush_staged_launch.log # f6.0: a staged rocket launches on a 390x844 phone (full fleet: STAGED_LAUNCH_LIMIT=999)
U=http://localhost:$PORT/ node tests/smoke/flight_gaps.cjs >/tmp/prepush_flight_gaps.log 2>&1 || { echo "FAIL flight_gaps"; fail=1; }; tail -1 /tmp/prepush_flight_gaps.log # f5.9-10: bars ≤30% (≤25% phone landscape) in orbit / after a craft switch, RELEASE double tap, End flight in ☰, end card closes the craft list
U=http://localhost:$PORT/ node tests/smoke/release_end_safe.cjs >/tmp/prepush_release_end_safe.log 2>&1 || { echo "FAIL release_end_safe"; fail=1; }; tail -1 /tmp/prepush_release_end_safe.log # QA f5.9-7: a double tap on RELEASE never ends the flight
U=http://localhost:$PORT/ node tests/smoke/staged_deploy.cjs electrino heron-9 >/tmp/prepush_staged_deploy.log 2>&1 || { echo "FAIL staged_deploy"; fail=1; }; tail -1 /tmp/prepush_staged_deploy.log # QA f5.9-9: AUTO drops the kick stage, RELEASE shows (full fleet: no ids)
U=http://localhost:$PORT/ node tests/smoke/booster_full.cjs >/tmp/prepush_booster_full.log 2>&1 || { echo "FAIL booster_full"; fail=1; }; tail -1 /tmp/prepush_booster_full.log # f5.9-10: expanded booster view
U=http://localhost:$PORT/ node tests/smoke/sheets_warp.cjs >/tmp/prepush_sheets_warp.log 2>&1 || { echo "FAIL sheets_warp"; fail=1; }; tail -1 /tmp/prepush_sheets_warp.log # f5.9-11: short Atlas, Settings/📍 targets ≥40px, key 0 at an apsis
U=http://localhost:$PORT/ node tests/smoke/census_sheets.cjs >/tmp/prepush_census.log 2>&1 || { echo "FAIL census_sheets"; fail=1; }; tail -1 /tmp/prepush_census.log # f5.9-12: QA census method for Atlas/Settings
U=http://localhost:$PORT/ node tests/smoke/bar_sheets_qa.cjs >/tmp/prepush_barsheets.log 2>&1 || { echo "FAIL bar_sheets_qa"; fail=1; }; tail -1 /tmp/prepush_barsheets.log # QA f5.9-12: THR inside the bar, desktop sheets close
U=http://localhost:$PORT/ node tests/smoke/site_sheet_close.cjs >/tmp/prepush_siteclose.log 2>&1 || { echo "FAIL site_sheet_close"; fail=1; }; tail -1 /tmp/prepush_siteclose.log # QA f5.9-13: 📍 sheet closes on Esc / outside tap
U=http://localhost:$PORT/ node tests/smoke/xfer_card_fit.cjs >/tmp/prepush_xferfit.log 2>&1 || { echo "FAIL xfer_card_fit"; fail=1; }; tail -1 /tmp/prepush_xferfit.log # QA f5.9-14: 🎯 card fits phone landscape (chips/verdict/actions visible)
U=http://localhost:$PORT/ node tests/smoke/map_ghost_tap.cjs >/tmp/prepush_mapghost.log 2>&1 || { echo "FAIL map_ghost_tap"; fail=1; }; tail -1 /tmp/prepush_mapghost.log # QA f5.9-16: one MAP tap on a phone never also opens the map ⋯ grid
U=http://localhost:$PORT/ node tests/smoke/map_phone.cjs >/tmp/prepush_mapphone.log 2>&1 || { echo "FAIL map_phone"; fail=1; }; tail -1 /tmp/prepush_mapphone.log # f5.9-17: phone portrait map usable (Tracking pill, centred focus, no label overlap)
U=http://localhost:$PORT/ node tests/smoke/bug_report.cjs >/tmp/prepush_bugreport.log 2>&1 || { echo "FAIL bug_report"; fail=1; }; tail -1 /tmp/prepush_bugreport.log # f5.9-18: in-game bug reports (card, screenshot, local queue, endpoint flush)
U=http://localhost:$PORT/ node tests/smoke/bug_note_keys.cjs >/tmp/prepush_bugnote.log 2>&1 || { echo "FAIL bug_note_keys"; fail=1; }; tail -1 /tmp/prepush_bugnote.log
U=http://localhost:$PORT/ node tests/smoke/pause_bar_fit.cjs >/tmp/prepush_pausebar.log 2>&1 || { echo "FAIL pause_bar_fit"; fail=1; }; tail -1 /tmp/prepush_pausebar.log
U=http://localhost:$PORT/ node tests/smoke/radial_plume_bells.cjs >/tmp/prepush_plumebells.log 2>&1 || { echo "FAIL radial_plume_bells"; fail=1; }; tail -1 /tmp/prepush_plumebells.log # art stages-pass-2: one plume per side booster, on its bell
[ -n "${NO_BUDGET:-}" ] || { node tests/smoke/ui_budget_smoke.cjs http://localhost:$PORT/ >/tmp/prepush_budget.log 2>&1 || { echo "FAIL ui_budget"; fail=1; }; tail -2 /tmp/prepush_budget.log
  # f5.8y (QA f5.8w): a row that FAILs in two runs in a row is real, not load: re-run the budget once when anything failed and fail the push on the FAIL rows common to both runs (the ratchet above still guards the pass count)
  if grep -q '^FAIL ' /tmp/prepush_budget.log && [ -z "${NO_RETRY:-}" ]; then node tests/smoke/ui_budget_smoke.cjs http://localhost:$PORT/ >/tmp/prepush_budget2.log 2>&1
    common=$(comm -12 <(grep '^FAIL ' /tmp/prepush_budget.log | awk '{print $2,$3,$4}' | sort -u) <(grep '^FAIL ' /tmp/prepush_budget2.log | awk '{print $2,$3,$4}' | sort -u))
    if [ -n "$common" ]; then echo "FAIL ui_budget rows failing in both runs:"; echo "$common"; fail=1; else echo "budget: FAIL rows differed between the two runs (load), none common"; fi; fi; }
gitleaks protect --staged --no-banner >/dev/null 2>&1 && gitleaks detect --no-banner --log-opts="origin/main..HEAD" >/dev/null 2>&1 || { echo "FAIL gitleaks"; fail=1; }
[ $fail = 0 ] && echo "prepush OK" || echo "prepush FAILED"; exit $fail
